/**
 * The console's own static assets: the HTML shell the browser opens, and the bundle it runs.
 *
 * The shell is generated by the control plane and never carries a credential: the browser is asked for the control-plane
 * key itself and keeps it in memory, so a page someone copied or a proxy that cached it holds no secret. The bundle is
 * the built file, served from the package's own directory; nothing is fetched from anywhere else, and the page's content
 * security policy says so.
 */
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

/** The name of the built bundle inside the console's directory. */
export const CONSOLE_BUNDLE = 'console.js'

/**
 * The content security policy of the console.
 *
 * The console is one origin and one origin only: no CDN, no font host, no analytics. `style-src` allows an inline
 * stylesheet because the bundle carries its own stylesheet and injects it into the document.
 */
export const CONSOLE_CSP = "default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; font-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"

/** Where the console's files live and how to serve them. */
export interface ConsoleAssetsOptions {
  /** The directory the built bundle lives in. */
  directory: string
}

/** The page a browser opens when the console was not built. */
const NOT_BUILT = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Superagent 控制台</title>
<style>
body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f7f7fb;color:#241f36;
font:14px/1.6 "Segoe UI","Microsoft YaHei UI",sans-serif}
main{max-width:520px;padding:28px 30px;background:#fff;border:1px solid #e7e2ef;border-radius:14px}
h1{margin:0 0 12px;font-size:20px;letter-spacing:-.02em}
p{margin:0 0 8px;color:#665f76}
code{background:#efebfb;color:#5636a8;border-radius:5px;padding:1px 5px;font-size:13px}
</style></head>
<body><main><h1>控制台前端尚未构建</h1>
<p>控制面已经在运行，但这个包里没有构建好的控制台页面。</p>
<p>请在源码目录执行 <code>pnpm build</code> 后重启控制面。</p>
<p>API 本身可用：<code>/v1/state</code>、<code>/v1/overview</code>、<code>/v1/audit</code>。</p>
</main></body></html>
`

/**
 * The console's static files.
 *
 * The bundle is read from disk when it is asked for, so a rebuilt console is picked up without a restart of the control
 * plane; the file is small and the read is local.
 */
export class ConsoleAssets {
  private readonly directory: string

  constructor(options: ConsoleAssetsOptions) { this.directory = options.directory }

  /** The path of the built bundle. */
  get bundlePath(): string { return join(this.directory, CONSOLE_BUNDLE) }

  /** Whether the console was built. */
  get built(): boolean { return existsSync(this.bundlePath) }

  /**
   * The HTML the browser opens.
   *
   * It is the shell of the console when the bundle exists, and a page that says the console was not built when it does
   * not: a blank page would tell an operator nothing.
   */
  shell(): string {
    if (!this.built) return NOT_BUILT
    return `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="referrer" content="no-referrer">
<title>Superagent 控制台</title>
</head>
<body>
<div id="root"></div>
<script type="module" src="/console/${CONSOLE_BUNDLE}"></script>
</body>
</html>
`
  }

  /** The built bundle, or `undefined` when the console was not built. */
  script(): Buffer | undefined {
    if (!this.built) return undefined
    try {
      return readFileSync(this.bundlePath)
    } catch {
      // The file disappeared between the check and the read; the caller answers as if it was never built.
      return undefined
    }
  }
}
